class Solution {
  public int findLatestStep(int[] arr, int m) {
    int n = arr.length;
    int[] len = new int[n + 2];
    int groups = 0, ans = -1;
    for (int step = 0; step < n; step++) {
      int x = arr[step], left = len[x - 1], right = len[x + 1];
      if (left == m) groups--;
      if (right == m) groups--;
      len[x] = left + right + 1;
      len[x - left] = len[x + right] = len[x];
      if (len[x] == m) groups++;
      if (groups > 0) ans = step + 1;
    }
    return ans;
  }
}
